# Context shim (see meta.json): sibling function from
# OntoUML/ontouml-json2graph@982f12b9c4 : json2graph/tests/test_main.py,
# copied VERBATIM (no I/O) so get_recorded_configuration -- which calls it
# but does not define it -- runs outside the test module. Identical shim
# imported by both original.py and translated.ldpy.
from rdflib import Graph, Namespace, URIRef

PROV = Namespace("http://www.w3.org/ns/prov#")


def get_output_artifact(metadata_graph: Graph) -> URIRef:
    """Return the single entity generated by a recorded transformation activity."""
    output_artifacts = set(metadata_graph.subjects(PROV.wasGeneratedBy, None))
    assert len(output_artifacts) == 1
    return next(iter(output_artifacts))
